   function nowRender(){const out=$('#now-grid');out.replaceChildren();[['building','BUILDING','One more idea.'],['learning','LEARNING','Figuring it out.'],['outside','OUTSIDE','The scenic route.']].forEach(([key,label,title])=>{const a=document.createElement('article');a.className='now-card';const l=document.createElement('span');l.className='eyebrow';l.textContent=label;const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=String(notes[key]).slice(0,600);a.append(l,h,p);out.append(a)});$('#now-label').textContent=JSON.stringify(notes)===JSON.stringify(defaults)?'A few things in progress.':'Local draft · saved on this device.';}
