   $('#edit-now').onclick=()=>{for(const k in defaults)$(`[name="${k}"]`,journal).value=notes[k];T.open(journal)};document.querySelector('#journal-form').onsubmit=e=>{e.preventDefault();notes=Object.fromEntries(new FormData(e.target));T.store.write('tom-now-local-v3',notes);nowRender();journal.close();T.notify('Local draft saved. Published content is unchanged.')};document.querySelector('#journal-reset').onclick=()=>{notes={...defaults};T.store.write('tom-now-local-v3',notes);nowRender();journal.close()};nowRender();
