   const data={nodexity:{name:'Nodexity',status:'The main project',origin:'My main independent project.',approach:'A connected technical visual direction. Try the interactive network study below to explore that direction.',challenge:'Giving an ambitious project a clear identity and space to develop.',state:'Featured here as my big project. Detailed product capabilities and release information are still to come.',next:'Keep building the project and document the real decisions along the way.'},gallery:{name:'GalleryX',status:'Project in development',origin:'A simpler way to browse a growing media library.',approach:'A Mac and Windows desktop gallery organized around scanning media, reviewing exports, identifying duplicates, and browsing video.',challenge:'Organizing a large collection without losing track of where the files actually live.',state:'The workflow and feature direction are defined. Try the illustrative media workflow below.',next:'Make discovery, duplicate review, and exports feel like one coherent workflow.'}};
