   $$('[data-story]').forEach(b=>b.onclick=()=>story(b.dataset.story));story('nodexity');
   const quick=$('.terminal-quick');['theme blue','theme random','open boat','timeline','surprise','lightsout'].forEach(c=>{const b=document.createElement('button');b.textContent=c;b.onclick=()=>{const output=$('#terminal-output');const q=document.createElement('p');q.className='terminal-command';q.textContent='tom ~ $ '+c;const a=document.createElement('p');a.textContent=T.command(c);output.append(q,a);output.scrollTop=output.scrollHeight};quick.append(b)});
